begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select is((select value from private.system_settings where key='admin_mfa_required'),'true'::jsonb,'MFA remains required by default');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.admin_get_overview()$$,'42501','MFA verification required','enabled policy rejects a single-factor admin session');
reset role;
update private.system_settings set value='false'::jsonb where key='admin_mfa_required';
set local role authenticated;
select is((public.get_admin_access()->>'mfaRequired')::boolean,false,'client can see that MFA is disabled');
select is((public.get_admin_access()->>'mfaVerified')::boolean,false,'disabled policy does not claim that MFA was verified');
select lives_ok($$select public.admin_get_overview()$$,'superadmin can operate while MFA is disabled');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000010',true);
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000010","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.admin_get_overview()$$,'42501','Superadmin access required','ordinary account owner cannot gain admin access');
select throws_ok($$select public.admin_update_system_setting('admin_mfa_required','false','Attempt unauthorized setting change')$$,'42501','Superadmin access required','ordinary owner cannot change MFA policy');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.admin_update_system_setting('admin_mfa_required','true','Re-enable second factor policy')$$,'22023','Подключите MFA и подтвердите код перед включением требования','reenabling requires configured and verified MFA');
select lives_ok($$select public.admin_close_account('20000000-0000-4000-8000-000000000002','УДАЛИТЬ АККАУНТ','Удаление по кнопке администратором')$$,'superadmin can close account without MFA while disabled');
select lives_ok($$select public.admin_close_account('20000000-0000-4000-8000-000000000002','УДАЛИТЬ АККАУНТ','Повтор запроса после сетевого сбоя')$$,'repeating deletion succeeds idempotently');
reset role;
select is((select count(*) from private.admin_audit_logs where action='admin.account.close' and account_id='20000000-0000-4000-8000-000000000002'),1::bigint,'repeated deletion produces one audit operation');
select is((select count(*) from public.accounts where id='20000000-0000-4000-8000-000000000002' and status='closed'),1::bigint,'deleted account is archived without foreign-key errors');
select * from finish();
rollback;
